import React from 'react'
type S={heading:string;text:string[]};type G={title:string;sections:S[]}
const guides:Record<string,G>={
"html-validator":{title:"HTML Validator",sections:[
{heading:"What HTML validation actually checks",text:["HTML validation compares a document's markup with the parsing and conformance rules defined for HTML. It can identify malformed nesting, duplicate attributes, invalid element placement, obsolete markup, missing required values and other structural problems. A validator is not a visual design grader: a page can look correct in one browser while still containing markup that is fragile, inaccessible or interpreted differently by another parser.","Use the report as a map of markup defects. The useful question is not simply whether the document has errors, but which error occurs first and whether later messages are consequences of that earlier defect."]},
{heading:"Document structure and parsing context",text:["A complete HTML document normally establishes a doctype, an html root, head metadata and a body. Elements are also constrained by content models: for example, list items belong in lists, table cells belong in rows, and interactive controls cannot be nested arbitrarily. Browsers perform error recovery when these rules are violated, which is why invalid markup may still render.","Validation exposes places where the browser has to guess. Correcting those places makes the DOM produced by different browsers, test runners, crawlers and accessibility tools more predictable."]},
{heading:"Fix the first structural error first",text:["One missing closing tag can cause a cascade of apparently unrelated messages because everything after it is parsed in the wrong context. When a report contains many errors, start near the earliest line and fix structural issues before polishing later warnings. Revalidate after each meaningful correction instead of attempting to repair every message at once.","This workflow is especially important around tables, forms, lists and deeply nested components. A single malformed ancestor can change how many descendants are interpreted."]},
{heading:"Attributes, IDs and form markup",text:["Attribute problems include duplicated attributes, malformed values and IDs that are reused where uniqueness is expected. Form controls deserve additional attention: labels should be associated with inputs, button types should be intentional, and attributes should match the element on which they are used. Valid syntax does not guarantee an accessible form, but invalid structure often makes accessibility behavior worse.","When generated frameworks render the final HTML, inspect the rendered output rather than assuming the source template is identical to what reaches the browser."]},
{heading:"Validation is different from accessibility testing",text:["A validator can confirm many syntactic relationships, but it cannot decide whether alternative text is meaningful, whether headings describe the page well, whether focus order makes sense, or whether color contrast is sufficient. Likewise, valid ARIA syntax does not prove that ARIA was used correctly.","Treat HTML validation as one layer of quality assurance. Pair it with keyboard testing, an accessibility checker, browser developer tools and, for important interfaces, assistive-technology testing."]},
{heading:"Semantic HTML improves more than validity",text:["Choosing elements for their meaning produces a clearer document outline and reduces dependence on custom roles. Headings, navigation landmarks, buttons, links, lists, tables and form controls each communicate behavior to browsers and assistive technologies. A generic div can be syntactically valid while still being a poor semantic choice.","When fixing an error, prefer a semantic correction over merely silencing the validator. Replacing an invalid clickable container with the appropriate button or link can improve keyboard behavior and accessibility at the same time."]},
{heading:"Frameworks, templates and generated HTML",text:["React, Next.js, Angular and server-side templates can hide the final nesting from the file being edited. Conditional rendering may also create invalid combinations only for certain states. If the validator accepts pasted HTML, validate the actual rendered document or the smallest reproduced fragment that still shows the problem.","Component boundaries do not exist to the HTML parser. A paragraph opened in one component and a block element returned by another still has to satisfy normal HTML parsing rules after composition."]},
{heading:"Warnings, obsolete features and compatibility",text:["Not every warning has the same severity. Obsolete presentational attributes may continue to work but should usually be replaced with CSS. Experimental or custom elements may require context before being treated as defects. Read the message and identify whether it describes a hard conformance error, an interoperability concern or a maintainability warning.","Avoid changing valid modern markup merely to satisfy an outdated rule set. The document type and validator mode should match the HTML version and environment you actually intend to support."]},
{heading:"A practical validation workflow",text:["Validate a representative page, fix the earliest structural errors, rerun the check, then address repeated component-level defects at their source. If the same invalid pattern appears on dozens of pages, repair the shared component rather than patching each rendered page. Add regression tests for markup that has caused production problems before.","For a large site, validation is most useful when integrated into development or CI on key templates. The goal is not a ceremonial zero-error badge; it is predictable markup that browsers, crawlers and accessibility APIs can interpret consistently."]},
{heading:"What a clean result does not prove",text:["A page with zero validator errors can still contain broken links, inaccessible interactions, misleading metadata, poor performance, unsafe scripts or incorrect business logic. Validation only answers a defined class of markup-conformance questions.","Use the HTML Validator to find structural defects efficiently, then continue testing the page as a real interface. Rendering, interaction, accessibility, SEO metadata and application behavior all require their own checks."]},
]},"css-clip-path":{title:"CSS Clip Path",sections:[
{heading:"How clip-path changes an element",text:["CSS clip-path defines the region of an element that remains visible. Pixels outside the clipping region are not painted even though the element still occupies its normal layout box. That distinction matters: clipping changes appearance, not document flow, so neighboring elements do not automatically move into the hidden area.","A generator is most useful for constructing the shape function and previewing it quickly. The resulting CSS should still be tested at the real element size because percentage coordinates respond to the element's box."]},
{heading:"Polygon coordinates",text:["polygon() describes a shape as a sequence of x/y coordinate pairs. Values such as 0% 0%, 100% 0% and 50% 100% correspond to points within the element's reference box. Connecting those points produces triangles, chevrons, stars and irregular panels without an SVG path.","Point order matters. Crossing edges can produce unexpected filled regions, so build complex polygons in a consistent clockwise or counter-clockwise sequence and preview the result at several aspect ratios."]},
{heading:"Inset, circle and ellipse shapes",text:["inset() clips inward from the top, right, bottom and left and can optionally use rounded corners. circle() uses a radius and center position, while ellipse() accepts separate horizontal and vertical radii. These basic shapes are easier to maintain than a long polygon when the desired geometry is simple.","Percentages are especially useful for responsive shapes because they scale with the element. Fixed pixel radii can be appropriate when the visual treatment must remain constant across differently sized elements."]},
{heading:"Reference boxes and percentage behavior",text:["Clipping coordinates are resolved against a reference box. In ordinary use that is closely related to the element's border box, but geometry-box keywords can change the reference in supported syntax. A point at 50% 50% therefore means the center of the chosen box, not the center of the viewport.","When a shape looks correct in the generator but wrong in production, compare the element dimensions, padding, borders and aspect ratio before changing every coordinate."]},
{heading:"Responsive design with clip-path",text:["A polygon designed for a wide hero banner may become distorted on a narrow card. Percentage points scale, but they do not preserve the visual intent of every shape. Test common breakpoints and consider separate shape values through media queries when the composition changes significantly.","For decorative diagonal edges, keep the number of points small. Simpler geometry is easier to reason about, less likely to create awkward slivers, and easier for future maintainers to adjust."]},
{heading:"Clipping versus masking",text:["clip-path creates a hard geometric boundary. CSS masks can represent gradients and partial transparency, making them better for fades, textured reveals and soft edges. Border-radius is simpler for rounded rectangles and circles when no irregular clipping is needed.","Choose the least complex technique that expresses the design. Using a 20-point polygon for a shape that border-radius can create adds unnecessary maintenance cost."]},
{heading:"Interaction and accessibility considerations",text:["Clipping is visual, so do not assume that a clipped design communicates state to screen readers. Essential text should remain readable and should not depend on a decorative cutout. Interactive elements also need generous visible hit areas and clear focus indicators after clipping.","If a focus ring is visually cut off, redesign the shape or focus treatment rather than removing the focus indicator. Keyboard users still need to see which control is active."]},
{heading:"Animation and morphing",text:["clip-path can be animated, but polygon morphs are most reliable when the start and end shapes use the same number of points. The browser interpolates corresponding coordinates over time. Large or constantly animated clipped regions can add rendering work, particularly on lower-powered devices.","Respect reduced-motion preferences for nonessential shape animations. A static final shape should preserve the same information and usability."]},
{heading:"Browser testing and fallbacks",text:["Modern browsers support common clip-path shapes well, but advanced path syntax and combinations can vary. Test the exact syntax you export rather than relying on a generic compatibility assumption. A sensible fallback is often the unclipped rectangular element, provided it remains visually acceptable.","Do not hide critical content solely because clipping support is unavailable. Progressive enhancement is safer for decorative shapes."]},
{heading:"Using generated CSS safely",text:["Copy the generated declaration into the smallest relevant selector, then inspect it in the actual component. Remove redundant points, format long polygons for readability and keep a comment when the geometry has a non-obvious purpose. If the same shape is reused, centralize it in a custom property or shared class.","The generator accelerates geometry authoring; the final quality check is whether the shape remains stable, readable and usable across the real layouts where it appears."]},
]},"string-hash-calc":{title:"String Hash Calculator",sections:[
{heading:"What a hash represents",text:["A hash function maps an input of arbitrary length to a fixed-size digest. The same bytes processed by the same algorithm produce the same digest, while even a small input change normally produces a very different result. This makes hashes useful for integrity checks, identifiers and comparisons where storing or transmitting the original content is unnecessary.","A digest is not an encrypted copy of the text. There is no decryption key that reconstructs the original input from a cryptographic hash."]},
{heading:"Text must become bytes first",text:["Hash algorithms operate on bytes, not abstract characters. A text tool therefore encodes the string, commonly as UTF-8, before hashing it. Visually similar strings can produce different byte sequences because of capitalization, whitespace, line endings or Unicode normalization.","When comparing a digest with another system, confirm the character encoding and exact input bytes. An invisible trailing newline is enough to change every hexadecimal character in the result."]},
{heading:"MD5 and SHA-1 are legacy choices",text:["MD5 and SHA-1 remain useful for non-adversarial checksums and compatibility with older systems, but collision attacks have made them unsuitable for security decisions that depend on collision resistance. A collision means two different inputs can be constructed to share the same digest.","Do not use MD5 or SHA-1 for digital signatures, certificate security or new tamper-resistant designs merely because their digests are shorter."]},
{heading:"SHA-2 and modern cryptographic hashes",text:["SHA-256 and SHA-512 are members of the SHA-2 family and remain common general-purpose cryptographic hash functions. The number in the name refers to digest size in bits, not to the amount of input accepted. A SHA-256 digest is 256 bits, commonly displayed as 64 hexadecimal characters.","Algorithm choice should match the protocol or application. Interoperability often matters as much as digest length when a hash must be reproduced elsewhere."]},
{heading:"Hashing is not password storage by itself",text:["Fast general-purpose hashes are intentionally efficient, which makes them poor standalone password-storage functions. Attackers can test enormous numbers of guesses quickly after obtaining a password-hash database. Password systems should use a dedicated password hashing or key-derivation function with a unique salt and an intentionally expensive work factor.","A string-hash calculator is useful for learning and checksums, but copying SHA-256(password) into a database is not a secure password-storage design."]},
{heading:"Salts, HMAC and keyed integrity",text:["A salt is random non-secret data combined with a password before a password-hashing function; it prevents identical passwords from sharing identical stored representations and frustrates precomputed tables. HMAC solves a different problem: it combines a cryptographic hash with a secret key to authenticate a message.","Plain hashing cannot prove who created a message because anyone can calculate the same digest. Use HMAC or a digital signature when authenticity, not just accidental-change detection, matters."]},
{heading:"Hex, Base64 and digest display",text:["The raw digest is binary data. Tools usually display it as hexadecimal or Base64 so it can be copied as text. Changing the display encoding does not change the underlying hash strength: hexadecimal simply uses two characters per byte, while Base64 is more compact.","When two digests look different, verify that both are represented in the same encoding before concluding that the underlying bytes differ."]},
{heading:"File checksums and integrity verification",text:["Software publishers often provide a SHA-256 checksum for a download. To verify it, hash the exact downloaded bytes and compare the complete digest with the value obtained from a trusted source. Matching values provide strong evidence that the file was not accidentally altered between those two observations.","A checksum copied from the same compromised location as a malicious file does not establish authenticity. Trust in the reference digest still matters."]},
{heading:"Avalanche effect and collision probability",text:["Cryptographic hashes are designed so a small input change causes widespread digest changes, often called the avalanche effect. You should not expect similar strings to have similar hashes. With a sufficiently large digest space, accidental collisions are extremely unlikely, although collision resistance also depends on the algorithm's cryptographic design.","Never compare only a short prefix when the hash is being used for a security-sensitive integrity check. Truncation reduces the number of possible values and therefore collision resistance."]},
{heading:"Reproducing a result correctly",text:["To reproduce a hash, preserve the exact text, encoding, algorithm and any preprocessing. Check whether spaces were trimmed, whether a newline was appended, whether Unicode was normalized and whether the tool hashes literal text or decoded data. These details explain most apparently inconsistent results.","Use this calculator as a deterministic transformation tool. For password security, signatures, API authentication or protocol design, follow the dedicated construction required by that security problem rather than inventing a scheme around a raw hash."]},
]},"env-file-parser":{title:"ENV File Parser",sections:[
{heading:"What an .env file contains",text:["An environment file commonly stores key-value assignments such as API_URL=https://example.com or PORT=3000. Libraries load those assignments into a process environment or configuration object. The format looks simple, but quoting, whitespace, comments, multiline values and variable expansion can differ between dotenv implementations.","A parser should therefore show how it interpreted each line rather than implying that every .env consumer follows one universal grammar."]},
{heading:"Keys, equals signs and whitespace",text:["A typical assignment has a key, an equals sign and a value. Values themselves may contain equals signs, so splitting every line on every equals sign can corrupt URLs, tokens or encoded data. Parsers generally treat the first delimiter as structural and preserve the remainder as part of the value.","Whitespace handling also matters. Some implementations trim unquoted surrounding whitespace while preserving whitespace inside quotes. Test the same syntax with the library used by your application when exact behavior is important."]},
{heading:"Quoted and unquoted values",text:["Quotes allow values to contain spaces and characters that would otherwise be ambiguous. Single-quoted and double-quoted strings may have different escape behavior depending on the parser. An unquoted # may begin a comment in some dotenv grammars, while a quoted # is normally literal data.","Do not remove quotes mechanically during cleanup. A value that appears equivalent to a human can parse differently after quote removal."]},
{heading:"Comments and blank lines",text:["Comments make environment templates understandable, and blank lines help group related configuration. A parser should ignore them as configuration entries while preserving enough context for diagnostics. Inline comments are particularly implementation-dependent when they follow an unquoted value.","For portable files, prefer simple full-line comments and quote values that intentionally contain comment-like characters."]},
{heading:"Variable expansion is not guaranteed",text:["Syntax such as BASE_URL=https://example.com followed by API_URL=${BASE_URL}/api may be expanded by some tools and left as literal text by others. Expansion can also introduce ordering and escaping rules. The basic dotenv concept does not guarantee shell-style substitution.","If your application depends on expansion, document the exact loader or plugin that performs it and test production behavior rather than relying on a generic parser preview."]},
{heading:"Environment files and secrets",text:[".env files often contain database passwords, API tokens and private keys. Parsing a file does not make those values safe. Secret-bearing files should normally be excluded from source control, protected with appropriate filesystem permissions and replaced by a secrets manager or deployment platform facility where operational risk justifies it.","Never paste production secrets into an online parser unless you trust its execution and data-handling model. Redact credentials when debugging configuration publicly."]},
{heading:"Client-side frameworks can expose values",text:["Environment variables used during a frontend build may be embedded into JavaScript delivered to every visitor. Frameworks commonly use naming conventions or explicit configuration to mark variables that are safe for browser exposure. A value being stored in .env does not make it server-only.","Treat any variable intentionally exposed to client code as public information. Private API keys and database credentials belong on a trusted server boundary."]},
{heading:"Types are usually strings",text:["Environment values generally enter an application as strings. The text false is still a non-empty string unless application code converts it to a boolean; 3000 is not automatically a validated port number. Robust applications parse and validate configuration at startup.","Schema validation can catch missing variables, malformed URLs, unsupported enum values and numeric ranges before the application begins serving traffic."]},
{heading:"Line endings and multiline data",text:["Files move between Unix and Windows environments with different line-ending conventions, and multiline certificates or JSON blobs can stress simplistic parsers. Some loaders support quoted multiline values; others expect escaped newlines or external files.","For large structured secrets, storing the value in a dedicated secret/file mechanism is often clearer than forcing complex data through a line-oriented dotenv format."]},
{heading:"Using parser output in practice",text:["Use the parser to inspect keys, identify malformed assignments and understand how a candidate file is tokenized. Then verify the result against the dotenv implementation actually used by the runtime. Keep a committed .env.example containing safe placeholder keys so required configuration is documented without exposing real secrets.","The most reliable configuration workflow combines parsing with startup validation, explicit defaults, secret separation and environment-specific deployment controls."]},
]},"base-converter":{title:"Base Converter",sections:[
{heading:"What a numeral base means",text:["A positional numeral system represents a number using powers of a base. Decimal uses powers of 10, binary uses powers of 2, octal uses powers of 8 and hexadecimal uses powers of 16. The written digits change between bases, but the underlying numerical value does not.","For example, decimal 26, binary 11010 and hexadecimal 1A are three representations of the same integer. A converter changes notation rather than changing the quantity."]},
{heading:"Place value explains every conversion",text:["In base b, the rightmost integer digit represents b^0, the next represents b^1, then b^2 and so on. Hexadecimal 1A therefore means 1×16 + 10×1 = 26. Binary 11010 means 16 + 8 + 2 = 26.","Understanding place value makes it possible to verify converter output manually and prevents confusion when digits such as A through F appear in hexadecimal."]},
{heading:"Valid digits depend on the base",text:["Binary permits only 0 and 1. Octal uses 0 through 7. Decimal uses 0 through 9. Hexadecimal adds A through F to represent values ten through fifteen. More general base converters may support additional symbols for bases above 16.","A digit must be smaller than the base. The string 102 is therefore invalid binary even though it is valid decimal and valid in any base of at least three."]},
{heading:"Converting an integer to decimal",text:["To convert from another base to decimal, multiply each digit value by its positional power and sum the terms. For binary 101101, the active positions are 32, 8, 4 and 1, giving decimal 45. This method works for any positional base when the digit values are known.","For long inputs, a converter automates the arithmetic, but the positional expansion remains a useful spot check."]},
{heading:"Converting decimal to another base",text:["For positive integers, repeated division is a common manual method. Divide by the target base, record the remainder, divide the quotient again and continue until the quotient is zero. Reading the remainders in reverse order gives the target representation.","Converting decimal 45 to binary produces remainders that read 101101; converting 45 to hexadecimal gives 2D because 45 = 2×16 + 13."]},
{heading:"Binary and hexadecimal map cleanly",text:["Because 16 is 2^4, each hexadecimal digit corresponds exactly to four binary bits. Hex A is 1010, F is 1111 and 3 is 0011. This makes hexadecimal a compact way to display binary values used in memory addresses, machine data, colors and bit masks.","Grouping a binary string into sets of four from the right allows fast binary-to-hex conversion without first converting the whole value to decimal."]},
{heading:"Leading zeros and representation",text:["Leading zeros do not change an ordinary integer's numerical value: binary 00101 and 101 both represent decimal 5. They can still be meaningful in fixed-width representations, network fields, machine words and formatted identifiers because they communicate width.","A generic number converter may remove leading zeros during normalization. Do not use that normalized output when exact byte width or textual formatting is itself significant."]},
{heading:"Negative numbers need a convention",text:["A minus sign followed by a magnitude, such as -1010₂, is straightforward mathematical notation. Computers may instead store signed integers using two's complement within a fixed bit width. The same bit pattern can therefore represent different values depending on whether it is interpreted as unsigned or signed and how many bits are assumed.","A base converter that accepts a leading minus sign is not automatically a two's-complement decoder. Check the tool's stated interpretation before using it for low-level binary data."]},
{heading:"Fractions and floating-point limits",text:["Digits to the right of a radix point use negative powers of the base. Binary 0.1 equals one half, while decimal 0.1 has no finite binary fractional representation. This is one reason floating-point calculations can contain small representation errors.","If the converter supports fractions, expect rounding when a value does not terminate in the target base. For exact financial or scientific work, the required precision and numeric representation should be chosen deliberately."]},
{heading:"Where base conversion is useful",text:["Programmers use binary and hexadecimal for bit operations, permissions, encodings, colors, protocol fields and debugging. Octal still appears in areas such as Unix permission notation. Decimal remains the usual human-facing representation for quantities.","Use this converter to translate and verify numeric representations, but distinguish numbers from encoded text. A hexadecimal string representing bytes or a cryptographic digest may look like a number while actually being structured data that should not be numerically converted."]},
]},"z-index-manager":{title:"Z Index Manager",sections:[
{heading:"What z-index actually controls",text:["CSS z-index controls paint order for positioned elements and for items that participate in particular stacking contexts. A larger number does not mean an element will appear above everything on the page. The value is compared only within the stacking context that contains it, which is why z-index bugs often survive even after developers try 9999 or 2147483647."]},
{heading:"Stacking contexts are the real model",text:["A stacking context is an isolated painting group. The root element creates one, and properties such as positioned elements with a non-auto z-index, opacity below 1, transforms, filters, isolation, and several containment features can create additional contexts. Descendants cannot escape their parent context merely by receiving a larger z-index."]},
{heading:"A common failure example",text:["Suppose a header has z-index 10 inside a parent stacking context whose sibling is painted at z-index 20. Giving the header z-index 100000 still leaves the entire parent context below the sibling. The fix is to understand and change the competing contexts, not keep increasing the child value."]},
{heading:"Build a small layer scale",text:["A maintainable application usually needs only a small semantic scale: normal content, sticky controls, dropdowns, overlays, modals and emergency notices. Centralizing those levels as CSS custom properties or design tokens prevents arbitrary values from spreading through components and makes intended relationships visible."]},
{heading:"Positioning and auto values",text:["Historically z-index is most commonly associated with relative, absolute, fixed and sticky positioning. Modern layout also allows flex and grid items to participate in stacking behavior in useful ways. An auto value generally leaves the item in its natural stacking level rather than establishing a deliberate numbered layer."]},
{heading:"Transforms and opacity surprises",text:["A transform used only for animation or GPU acceleration can unexpectedly create a stacking context. Opacity, filters, perspective and isolation can do the same. When a dropdown appears behind an unrelated panel, inspect ancestors in browser developer tools for these context-creating properties before changing the dropdown number."]},
{heading:"Portals and modal systems",text:["Framework modal and tooltip libraries often render through a portal near the document body so they are not trapped by local overflow or stacking contexts. A z-index manager should account for where an overlay is actually mounted. Two libraries with independent layer scales can still conflict even if each works correctly alone."]},
{heading:"Overflow is a different problem",text:["An element can have the correct z-index and still be clipped by an ancestor with overflow hidden, clip or certain containment settings. z-index changes painting order; it does not automatically remove clipping. Diagnose whether the symptom is occlusion by another element or geometric clipping by an ancestor."]},
{heading:"Debugging workflow",text:["Inspect the two elements that overlap, identify their nearest stacking-context ancestors, and compare those ancestors at the level where they are siblings. Temporarily remove transforms or z-index declarations to confirm the cause. Once understood, use the smallest semantic layer change that restores the intended order."]},
{heading:"Accessibility and interaction",text:["Visual layering must match interaction layering. A modal shown above a page should also manage keyboard focus and prevent accidental interaction with obscured content. A high z-index alone does not make an overlay accessible. Test focus order, escape behavior, screen-reader labeling and pointer interaction."]}
]},
"wealth-calculator":{title:"Wealth Calculator",sections:[
{heading:"Define wealth before projecting it",text:["A wealth calculator is most useful when “wealth” is defined as net worth: assets minus liabilities. Investment accounts, cash, property equity and business interests can increase the asset side, while mortgages, student loans, credit balances and other debts reduce the amount economically owned. A projection that grows investments but ignores debt can overstate financial position. Begin with a consistent snapshot date and avoid counting the full property value plus home equity as separate assets."]},
{heading:"Starting capital has a large compounding effect",text:["Money already invested receives the full benefit or loss of every future period in the projection. A person starting with ₹10 lakh and adding ₹20,000 monthly has a different path from someone starting at zero even if future contributions are identical. Verify whether the calculator treats the starting value as investable assets, total net worth, or another measure. Illiquid assets such as a primary residence do not compound at the same assumed portfolio return unless the model explicitly treats them that way."]},
{heading:"Contributions drive outcomes you can control",text:["Regular saving is often more controllable than market returns. Monthly or annual contributions should match the timing convention used by the formula because contributions made at the beginning of a period compound slightly longer than those made at the end. If income is irregular, a smooth monthly assumption is a planning simplification. Testing several contribution levels shows how much of the projected wealth comes from behavior versus assumed investment performance."]},
{heading:"Return assumptions should be nominal or real",text:["A nominal return includes inflation in the future money amounts, while a real return expresses growth in today’s purchasing power. Mixing a nominal investment return with an inflation-adjusted goal creates an inconsistent projection. If the calculator does not separately model inflation, decide whether the entered return is intended to be nominal and then interpret the future balance accordingly. Long horizons magnify even small changes in the assumed annual return."]},
{heading:"Compounding is nonlinear",text:["Compound growth means each period’s return applies to prior gains as well as original capital. This is why doubling the investment horizon can more than double the growth portion of a projection. It also means an unrealistic return assumption becomes increasingly damaging over decades. Compare a conservative, middle and optimistic return range, but do not treat the highest path as a forecast. Markets produce uneven yearly returns rather than the smooth line shown by a constant-rate model."]},
{heading:"Debt belongs in the wealth picture",text:["Paying down debt can increase net worth even when no new investment asset is created, because liabilities fall. High-interest debt also creates a relatively certain financing cost that may exceed the expected return of risky investments. A wealth projection that excludes debt payoff should be read as an asset-growth model, not a complete net-worth plan. Mortgage principal reduction, in particular, can build home equity while cash flow leaves the household."]},
{heading:"Taxes and account types affect usable wealth",text:["A ₹1 crore balance in a taxable account, a tax-deferred retirement account and a tax-free account may not provide identical after-tax spending power. Capital-gains taxes, dividend taxation, withdrawal rules and future income-tax rates can alter what the headline balance is worth to the owner. A simple calculator may omit these details. Use the projection as a gross accumulation estimate unless the tool explicitly models account-specific taxes and withdrawal consequences."]},
{heading:"Fees quietly reduce compounding",text:["Investment expense ratios, advisory fees, transaction costs and product charges reduce the return that remains available to compound. The gap between 8% gross and 7% net may appear modest in one year but can create a large difference over 20 or 30 years. When possible, enter a return assumption after expected recurring fees. One-time costs should be deducted separately rather than hidden inside an annual return estimate."]},
{heading:"Inflation changes the meaning of a future crore",text:["A future balance can look impressive while buying less than the same nominal amount buys today. To estimate purchasing power, discount the projected balance by an assumed inflation rate or use a real-return framework. This is especially important for retirement, education and long-term independence goals. Inflation itself is uncertain, so the goal is not to predict a perfect future price level but to avoid comparing future rupees directly with today’s lifestyle costs."]},
{heading:"Sequence of returns matters near withdrawals",text:["During pure accumulation with regular contributions, a constant average return is a reasonable simplification for illustration. Once withdrawals begin, the order of market gains and losses becomes much more important. Large losses early in retirement can permanently damage a portfolio even if the long-run average return later recovers. A wealth accumulation result therefore should not automatically be reused as a retirement-income sustainability result."]},
{heading:"Worked projection logic",text:["Consider ₹5 lakh already invested, ₹25,000 added each month and a 7% annual return over 15 years. The future value has two components: growth of the starting ₹5 lakh and the accumulated future value of the monthly contribution stream. The final amount is not simply total contributions plus 7% multiplied by 15. Each contribution compounds for a different number of months. A manual check can separately estimate the lump-sum and recurring-contribution portions."]},
{heading:"Turn the projection into a plan",text:["Use the output to identify the saving rate and time horizon required for a target, then stress-test the variables that are genuinely uncertain. Revisit the projection after major income changes, debt payoff, asset purchases or market movements instead of assuming the original path remains valid forever. Track actual net worth alongside the model. The calculator is strongest as a planning map that links starting assets, contributions, time and return assumptions—not as a promise of future wealth."]},
]},
"hash-generator":{title:"Hash Generator",sections:[
{heading:"Hashing maps data to a fixed-size digest",text:["A hash function consumes input bytes and produces a digest. Cryptographic hashes such as SHA-256 are deterministic: identical bytes produce identical digests, while even a tiny input change normally produces a very different result. The digest is not a compressed copy from which the original text can be recovered."]},
{heading:"Text must become bytes first",text:["Hash algorithms operate on bytes, not abstract characters. A text tool normally encodes input as UTF-8 before hashing it. ASCII text maps simply, while accented characters, emoji and other Unicode characters may occupy multiple bytes. Two visually similar Unicode strings can therefore hash differently if their underlying code-point sequences differ."]},
{heading:"SHA-256, SHA-512 and older algorithms",text:["SHA-256 and SHA-512 remain common general-purpose cryptographic hash choices. MD5 and SHA-1 are still encountered for legacy checksums but have known collision weaknesses and should not be selected where collision resistance is a security requirement. Algorithm choice should follow the actual protocol or security goal."]},
{heading:"Hashing is not encryption",text:["Encryption is designed to be reversible with the appropriate key. Hashing is one-way by design. If an application needs to recover plaintext later, a hash is the wrong primitive. Conversely, encrypting passwords so they can be decrypted is usually the wrong storage model."]},
{heading:"Password storage needs slow password hashing",text:["Fast general-purpose hashes are intentionally efficient, which helps attackers test huge numbers of password guesses. Password databases should use a dedicated password-hashing or key-derivation function such as Argon2id, scrypt, bcrypt or an appropriate PBKDF2 configuration, with a unique random salt and suitable work parameters."]},
{heading:"HMAC authenticates with a secret",text:["A plain digest can detect accidental changes when compared with a trusted reference, but anyone can calculate it. HMAC combines a cryptographic hash with a secret key so a recipient who knows the key can verify message integrity and authenticity. Do not invent a keyed scheme by simply concatenating a secret and message."]},
{heading:"Hex and Base64 are display encodings",text:["The digest itself is binary. Hexadecimal represents each byte with two hex characters; Base64 is more compact. Converting a digest from hex to Base64 does not re-hash it or change its cryptographic strength. Comparisons should decode or use the same representation consistently."]},
{heading:"File checksum verification",text:["To verify a download, hash the exact file bytes and compare the full digest with a checksum obtained from a trusted source. A matching SHA-256 value is strong evidence the bytes match that reference. It does not prove safety if both the file and reference checksum came from the same compromised source."]},
{heading:"Collisions and the avalanche effect",text:["A collision occurs when two different inputs produce the same digest. Secure modern hashes are designed to make useful collision attacks infeasible and to exhibit an avalanche effect, where small input changes alter many output bits. Truncating a digest reduces its collision resistance because fewer possible values remain."]},
{heading:"Practical test cases",text:["Try an empty string, ordinary ASCII, trailing spaces, line breaks, accented text and emoji. Confirm whether the tool preserves whitespace and which character encoding it uses. When matching another system, compare the exact bytes, algorithm and output encoding before treating a mismatch as a hashing defect."]}
]},
"url-encoder":{title:"URL Encoder",sections:[
{heading:"Why URLs need percent-encoding",text:["URLs use a defined syntax in which some characters have structural meaning. Percent-encoding represents a byte as a percent sign followed by two hexadecimal digits, allowing data characters to travel without being mistaken for delimiters. A space, for example, is commonly represented as %20 in a URI component. Encoding is about preserving syntax during transport; it is not encryption, compression or a security boundary."]},
{heading:"Encode components, not an entire URL blindly",text:["A complete URL contains a scheme, host, path, query delimiters and fragment markers. Encoding the whole string with a component encoder can turn characters such as : / ? & and = into data and destroy the URL structure. The safer pattern is to encode each user-supplied component at the point where it is inserted. A path segment, query value and full URI have different sets of characters that may remain unescaped."]},
{heading:"Reserved characters have meaning",text:["Characters such as /, ?, #, [, ], @, !, $, &, apostrophe, parentheses, *, +, comma, semicolon, colon and equals can be reserved by URI syntax or by a component’s sub-syntax. Whether a reserved character should be encoded depends on whether it is intended as syntax or literal data. An ampersand separating query parameters should remain a delimiter; an ampersand inside a parameter value generally needs encoding so it is not parsed as a new parameter."]},
{heading:"Percent-encoding works on bytes",text:["Percent escapes represent bytes, so non-ASCII text must first be converted to an agreed character encoding, normally UTF-8 on the modern web. A Unicode character can therefore become multiple %HH sequences. This is why simply converting a character’s code point to one hexadecimal number is not a correct general URL encoder. Correct UTF-8 handling is essential for names, international text and emoji."]},
{heading:"Spaces: %20 versus plus",text:["In general URI percent-encoding, a space is represented as %20. HTML form encoding for query data historically uses + for a space and percent-encodes a literal plus sign. These conventions are related but not identical. A decoder must know which format it is processing; blindly changing every plus into a space can corrupt data where + was intended literally. Library APIs often expose separate URI-component and form/query helpers for this reason."]},
{heading:"Avoid accidental double encoding",text:["If a value already contains %20 and it is passed through an encoder again, the percent sign may become %25, producing %2520. The receiver then needs an extra decoding pass to recover the original space, which is often a bug and can create security inconsistencies. Decide where encoding occurs in the application and do it exactly once for each boundary. Do not try to detect encoded strings solely by looking for percent signs because literal percent characters are valid input data."]},
{heading:"Path segments need special care",text:["A slash separates path segments, so a user value containing a literal slash cannot always be inserted into a path without encoding or redesigning the route. Dot segments such as . and .. also have navigation semantics in URL processing. Framework routers may decode paths before application code sees them. When identifiers can contain arbitrary text, use the framework’s route-building utilities and test encoded slashes, Unicode and trailing delimiters rather than concatenating strings manually."]},
{heading:"Query parameters should use a query builder",text:["Constructing a query by concatenating ?name= plus raw input is fragile. A query-parameter API can encode keys and values, preserve repeated parameters and handle delimiters consistently. It also makes the difference between an absent parameter, an empty value and a literal string clearer. If the same key appears multiple times, application semantics determine whether order and repetition are meaningful; URL encoding alone does not resolve that."]},
{heading:"Fragments are client-side identifiers",text:["The portion after # is a fragment and is normally not sent to the server as part of an HTTP request target. It can identify a document section or carry client-side application state. Encoding a fragment value follows URI rules, but developers should not expect server code to receive it. Sensitive information should not be placed in fragments merely because it is absent from ordinary server request logs; browsers, scripts and history can still expose it."]},
{heading:"Encoding does not make input safe",text:["Percent-encoding can preserve URL syntax, but it does not sanitize SQL, HTML, shell commands or authorization decisions. A decoded value can still contain malicious or unexpected content. Validate inputs according to their destination and use context-specific escaping or parameterization. Open redirects, path traversal and SSRF are application-security problems that are not solved by calling a URL encoder."]},
{heading:"Decoding and error handling",text:["A decoder reverses valid percent escapes and then interprets bytes using the expected character encoding. Malformed sequences such as a lone % or non-hexadecimal digits should be handled deliberately rather than silently producing unpredictable output. Some platforms throw an exception for invalid encodings. If the tool is used to inspect third-party URLs, preserve the original input so a failed decode does not destroy evidence of what was received."]},
{heading:"Practical test cases",text:["Test plain ASCII, spaces, plus signs, ampersands, equals signs, slashes, percent signs, Unicode words and emoji. Also test a value that already contains an escape such as %2F to expose double-encoding behavior. Compare the result with the standard URL/URI API in the target programming language. The goal is not to maximize the number of escaped characters; it is to preserve the intended data while keeping URL syntax unambiguous."]},
]},
"pregnancy-calculator":{title:"Pregnancy Calculator",sections:[
{heading:"What a pregnancy calculator can estimate",text:["A pregnancy calculator estimates gestational age and an expected due date from dating information such as the first day of the last menstrual period or another date accepted by the tool. The result is an estimate, not a prediction of the exact day labor will begin. Pregnancy dating is conventionally expressed in completed weeks and days from the start of the last menstrual period, which means the obstetric gestational age begins roughly two weeks before conception in a typical cycle."]},
{heading:"The 40-week convention",text:["A common menstrual dating method counts about 280 days, or 40 weeks, from the first day of the last menstrual period. This convention assumes a cycle pattern close to the model used by the calculator. It is useful because the LMP is often easier to identify than the exact day of fertilization. Only a minority of births occur on the calculated due date, so the date should be understood as the center of an expected delivery window rather than an appointment set by biology."]},
{heading:"Cycle length and ovulation timing",text:["The classic LMP rule implicitly assumes ovulation around the middle of a roughly 28-day cycle. People with consistently longer cycles may ovulate later, while shorter cycles can shift ovulation earlier. Irregular cycles make menstrual dating less reliable because the interval between menstruation and ovulation is not fixed. If the calculator provides a cycle-length adjustment, it is still an approximation; cycle length alone cannot identify the actual ovulation day in a particular month."]},
{heading:"Conception date is usually an estimate",text:["Even when intercourse or insemination dates are known, conception cannot always be assigned to a single calendar day because sperm can remain viable for several days and ovulation timing can vary. Assisted-reproduction pregnancies can have more precise procedural dates, but their clinical dating follows specific conventions. A general-purpose calculator should not replace the dating method supplied by a fertility clinic or obstetric professional when embryo-transfer or other assisted-reproduction dates are involved."]},
{heading:"Ultrasound dating",text:["Early ultrasound can provide a more reliable gestational-age estimate when the menstrual date is uncertain, cycles are irregular, or measured development differs enough from LMP dating to meet clinical redating criteria. First-trimester measurements are particularly useful because biological size variation is smaller early in pregnancy than later. A website calculator does not see ultrasound measurements, so its result should not be used to override a due date established by the clinician caring for the pregnancy."]},
{heading:"Gestational age versus fetal age",text:["Gestational age and fetal or conception age are not interchangeable. Obstetric gestational age is counted from the LMP convention, while conception generally occurs later. This is why someone described as four weeks pregnant has not usually had four weeks of embryonic development. Keeping the terminology straight prevents apparent two-week discrepancies when comparing apps, laboratory references or educational material."]},
{heading:"Trimester boundaries are approximate",text:["Pregnancy is often divided into three trimesters for communication and care planning, but exact boundary conventions can vary slightly among sources. A calculator may map the current gestational week into a trimester for convenience. That label should not be interpreted as a diagnostic threshold by itself. Screening windows, anatomy scans, glucose testing and other prenatal events have their own recommended timing and should follow the schedule provided by the relevant healthcare professional."]},
{heading:"Due date is a range, not a deadline",text:["Normal delivery can occur before or after the estimated due date. The clinical meaning of early-term, full-term, late-term and post-term gestation depends on completed weeks, not on whether the calendar has crossed the estimated due date by one day. Users should avoid interpreting a due date as evidence that something is wrong if labor has not started that morning. Decisions about monitoring or induction are individualized and belong with maternity care."]},
{heading:"When LMP dating becomes unreliable",text:["LMP-based estimates can be less dependable after recent pregnancy, during breastfeeding, after stopping hormonal contraception, with irregular bleeding, with very irregular cycles, or when the remembered date was spotting rather than a true menstrual period. In those cases the arithmetic can still produce a precise-looking date while the starting assumption is weak. Entering an uncertain date with more digits does not improve its clinical accuracy."]},
{heading:"Worked dating example",text:["If the first day of the last menstrual period was January 1, adding approximately 280 days gives an expected due date in early October. At 12 weeks after January 1, the pregnancy is described as about 12 weeks gestational age even though conception likely occurred later than January 1. This example illustrates the convention; actual month lengths, leap years and the calculator’s date arithmetic determine the exact displayed date."]},
{heading:"Symptoms are not part of date arithmetic",text:["Nausea, breast tenderness, fatigue, fetal movement and abdominal size vary widely and are not reliable substitutes for formal pregnancy dating. A due-date calculator should not be used to judge whether symptoms are normal or whether a pregnancy is progressing normally. Pain, bleeding, severe vomiting, reduced fetal movement later in pregnancy, or other concerning symptoms require appropriate medical assessment rather than recalculating the due date."]},
{heading:"Best way to use this tool",text:["Use the result as an educational planning estimate for gestational weeks, approximate milestones and a preliminary due date. Record the input method used so that LMP dating is not accidentally compared with an ultrasound-based clinical date as though they were generated the same way. Once prenatal care establishes an official estimated due date, use that clinical date for medical decisions and appointment timing. The calculator is most useful for orientation, not diagnosis or emergency guidance."]},
]},
"json-to-csv":{title:"JSON To CSV",sections:[
{heading:"JSON and CSV represent data differently",text:["JSON can represent objects, arrays, nested structures, booleans, null and numbers. CSV is fundamentally a rectangular table of rows and columns. Converting JSON to CSV therefore requires a mapping decision: which JSON objects become rows, which properties become columns, and what happens to nested values."]},
{heading:"The easiest input is an array of flat objects",text:["An array such as [{name:\"A\",age:20},{name:\"B\",age:30}] maps naturally to a header row and two data rows. Real data is often irregular: later objects may omit keys or introduce new ones. A converter must decide whether the header is a union of all keys or is derived from only the first object."]},
{heading:"Nested objects need a flattening policy",text:["A property like address.city has no native CSV nesting. Tools may flatten it to a dotted column name, stringify the nested object as JSON, or omit unsupported structure. Each choice affects downstream use. Flattening is convenient for analytics but can create ambiguous names when original keys already contain separators."]},
{heading:"Arrays are even more ambiguous",text:["An array property might be joined into one cell, JSON-stringified, expanded into numbered columns, or exploded into multiple rows. There is no universally correct conversion. Tags may work as a joined string, while line items in an invoice often require a separate child table or row-expansion strategy."]},
{heading:"CSV quoting rules protect delimiters",text:["A cell containing the delimiter, a quote or a line break must be escaped according to the target CSV convention, commonly by wrapping the field in double quotes and doubling embedded double quotes. Simply joining values with commas produces corrupt output as soon as user data contains punctuation."]},
{heading:"Null, missing and empty are not identical",text:["JSON distinguishes a missing property, explicit null and an empty string. A basic CSV export may render all three as an empty cell, losing information. If that distinction matters, choose explicit sentinel values or preserve a schema alongside the export."]},
{heading:"Numbers and identifiers require care",text:["Spreadsheet programs may reinterpret long account numbers, leading zeros, dates and scientific-looking strings. A JSON value that is semantically an identifier should not automatically become a numeric spreadsheet value. CSV has no built-in type metadata, so consumers infer types independently."]},
{heading:"Character encoding matters",text:["UTF-8 is the safest default for multilingual data, but some spreadsheet workflows expect a byte-order mark or locale-specific delimiter. Test names with accents, non-Latin scripts and emoji. Encoding corruption is often discovered only after the CSV is opened in a different program."]},
{heading:"Formula injection is a security concern",text:["Spreadsheet applications can treat cells beginning with characters such as =, +, - or @ as formulas. Exporting untrusted user input directly to CSV can therefore create formula-injection risk when a recipient opens the file. High-risk exports should neutralize or safely handle formula-like cells according to the consuming application."]},
{heading:"Validate with round-trip samples",text:["Test commas, quotes, multiline text, nulls, missing keys, nested objects, arrays and Unicode. Open the generated file in the intended spreadsheet or import pipeline and confirm row and column counts. A successful conversion is one whose mapping rules are explicit and whose output survives the actual consumer."]}
]},
"json-formatter":{title:"JSON Formatter",sections:[
{heading:"Formatting changes presentation, not data",text:["A JSON formatter parses valid JSON and serializes the same data with consistent indentation and line breaks. Pretty-printing should not change object values, array order, strings, booleans, numbers or null. Minifying performs the opposite presentation step by removing unnecessary whitespace."]},
{heading:"JSON has strict syntax",text:["JSON uses double-quoted property names and strings, does not allow comments in the standard grammar, and does not permit trailing commas. Values are objects, arrays, strings, numbers, true, false or null. JavaScript object-literal syntax is broader, so text that works inside source code may still be invalid JSON."]},
{heading:"Parser errors often point near the symptom",text:["A missing comma, quote or closing bracket can make the parser complain on a later token. When formatting fails, inspect the reported position and the structure immediately before it. Bracket matching and syntax highlighting make deeply nested errors easier to isolate."]},
{heading:"Indentation is a readability choice",text:["Two spaces, four spaces and tabs can all represent the same parsed JSON. Smaller indentation reduces visual width; larger indentation can make shallow structures easier to scan. Teams should choose a convention through tooling rather than debating it per file."]},
{heading:"Object key order should not carry business meaning",text:["Many runtimes preserve insertion order for practical purposes, but JSON objects conceptually represent name/value members rather than an ordered list. If order is semantically important, represent it explicitly as an array. A formatter should not be used as a mechanism for encoding hidden meaning through key position."]},
{heading:"Large numbers can lose precision in consumers",text:["JSON syntax permits numbers that exceed JavaScript Number safe-integer precision. A formatter implemented through normal JavaScript parsing may round such values even though the original text looked exact. Large IDs are often safer represented as strings when exact digits must survive heterogeneous systems."]},
{heading:"Escapes and Unicode",text:["JSON strings use escapes for quotes, backslashes and control characters, and can use Unicode escape notation. Formatting should preserve the represented string value even if the serialized spelling changes. Visually similar Unicode sequences can still be distinct values."]},
{heading:"Minification is not compression",text:["Removing whitespace reduces text size but does not apply a compression algorithm. HTTP gzip or Brotli can often reduce repetitive JSON much further. Use minification for compact source or payload representation, and transport compression for network efficiency where supported."]},
{heading:"Never paste secrets casually",text:["Online formatters may receive API keys, tokens, customer records or production payloads. Treat sensitive JSON according to the tool deployment model. A local/offline formatter is preferable when policy prohibits sending data to third-party services."]},
{heading:"A useful validation workflow",text:["Format a sample, confirm the parser accepts it, compare parsed values before and after, and test edge cases such as empty arrays, escaped newlines, Unicode and very large numbers. For API contracts, JSON Schema or application-level validation is still required because syntactically valid JSON can contain the wrong fields and types."]}
]},
"open-graph-preview":{title:"Open Graph Preview",sections:[
{heading:"Open Graph metadata controls link previews",text:["Open Graph tags provide structured metadata that social platforms and messaging apps can use when a URL is shared. Core properties commonly include og:title, og:description, og:image and og:url. The preview tool helps inspect how those values combine, but each platform ultimately decides what to display."]},
{heading:"Title and description should match the destination",text:["A preview title should identify the page accurately rather than act as unrelated clickbait. Descriptions work best when they summarize the page in a compact sentence or two. Platforms may truncate or rewrite text, so the most important meaning should appear early."]},
{heading:"Image selection has outsized impact",text:["The social image is often the largest part of a preview. Use an image that remains understandable after cropping and downscaling, keep important text away from edges, and avoid tiny typography. Platforms differ in aspect ratio and may cache older images."]},
{heading:"Use absolute, crawlable image URLs",text:["Social crawlers fetch metadata without the browser context available to a normal visitor. Relative image paths, authentication-protected assets, blocked user agents or short-lived signed URLs can prevent the image from loading. Public absolute HTTPS URLs are the most interoperable choice."]},
{heading:"Canonical URL and og:url solve related problems",text:["og:url identifies the URL associated with the Open Graph object, while rel=canonical is primarily a search-engine canonicalization signal. They often point to the same preferred URL but serve different consumers. Tracking parameters should not accidentally create many inconsistent preview identities."]},
{heading:"Twitter/X and other platforms may use extra tags",text:["Some services support their own metadata, such as twitter:card and related fields, while falling back to Open Graph for missing values. A generic preview cannot guarantee pixel-perfect rendering across every service. Test important pages with the official sharing/debugging tools of target platforms."]},
{heading:"Server-rendered metadata matters",text:["Many crawlers do not execute client-side JavaScript like a full browser. Metadata that appears only after hydration may therefore be invisible to a scraper. Framework applications should ensure share metadata is present in the initial server-rendered HTML for the requested URL."]},
{heading:"Caching explains stale previews",text:["Social networks commonly cache metadata and images after the first scrape. Updating a tag does not guarantee an immediate visual change when the same URL is shared again. Platform debugging tools can sometimes request a re-scrape, while changing image URLs is another common cache-busting technique."]},
{heading:"Image dimensions and content safety",text:["Provide sufficiently large source images and explicit image metadata when the platform supports it. Avoid placing essential claims solely inside the image because users with images disabled or assistive technologies may not receive that information. og:image:alt can improve descriptive metadata where supported."]},
{heading:"Preview versus production verification",text:["Use the preview to catch missing fields, awkward truncation and poor image composition, then inspect the actual HTML and fetchability of every referenced asset. The final test is a real scrape on the platforms that matter because their rendering rules, cache and moderation systems are outside the page developer\u2019s control."]}
]},
"sql-join-visualizer":{title:"SQL Join Visualizer",sections:[
{heading:"A join combines rows through a condition",text:["SQL joins relate rows from two data sources using an ON condition, commonly equality between a foreign key and a primary or candidate key. The visual overlap metaphor is useful for learning which unmatched rows survive, but real joins operate on rows and predicates rather than geometric sets."]},
{heading:"INNER JOIN keeps matching combinations",text:["An INNER JOIN returns row combinations for which the join predicate is true. If one customer has three matching orders, that customer can appear three times. This multiplicity is fundamental: joins do not automatically deduplicate data."]},
{heading:"LEFT JOIN preserves the left side",text:["A LEFT OUTER JOIN keeps every row from the left input and adds matching right-side values when available. For an unmatched left row, right-side columns are null. This is useful for finding optional related data or identifying left-side records with no match."]},
{heading:"RIGHT and FULL OUTER JOIN",text:["RIGHT JOIN mirrors LEFT JOIN with the preserved side reversed and can often be rewritten by swapping table order. FULL OUTER JOIN preserves unmatched rows from both inputs, which is useful for reconciliation. Not every database supports FULL OUTER JOIN directly."]},
{heading:"CROSS JOIN creates a Cartesian product",text:["A CROSS JOIN pairs every left row with every right row. Ten rows crossed with twenty rows produce two hundred combinations. This is useful for grids and generated combinations but can explode unexpectedly if a join condition is accidentally omitted."]},
{heading:"NULL requires special reasoning",text:["SQL NULL represents an unknown or missing value and does not compare equal to another NULL with ordinary equality. Rows with null join keys therefore do not match under a.key = b.key. If null-equivalence is intended, use database-appropriate null-safe logic explicitly."]},
{heading:"Filters can accidentally change outer joins",text:["A classic mistake is LEFT JOIN followed by WHERE right.status = active. Unmatched rows have null right-side values, so the WHERE clause removes them and the result behaves more like an inner join. Conditions intended only for matching often belong in the ON clause."]},
{heading:"Many-to-many joins multiply rows",text:["If both sides contain repeated join keys, each matching left row combines with each matching right row. Two matching rows on one side and three on the other produce six rows. Unexpected totals after a join often come from cardinality assumptions rather than arithmetic errors."]},
{heading:"Join keys and performance",text:["Indexes on appropriate join/filter columns can make large joins dramatically faster, but the optimizer also considers table size, statistics, selectivity and join algorithm. Functions or implicit type conversions on join keys may prevent efficient index use. Examine the execution plan for production performance questions."]},
{heading:"Use the visualizer, then verify with sample tables",text:["Create tiny tables where keys include matches, unmatched values, duplicates and nulls. Predict the output before running each join type, then compare row counts and values. This makes the difference between row preservation and row multiplication concrete and transfers directly to debugging real SQL."]}
]},
"password-generator":{title:"Password Generator",sections:[
{heading:"Password strength begins with unpredictability",text:["A generated password is useful when its characters are selected with a cryptographically secure random source rather than a predictable pseudo-random sequence. The goal is to make each candidate hard to guess even when an attacker knows the generation method."]},
{heading:"Length usually matters more than cosmetic complexity",text:["Adding character classes increases the size of the candidate space, but length is a powerful contributor to entropy. A long independently generated password is generally stronger than a short password that merely satisfies many composition rules. Service-specific maximum lengths and allowed characters still matter."]},
{heading:"Entropy is a model, not a guarantee",text:["For truly uniform random selection from an alphabet of N symbols, a length-L password has approximately L \u00d7 log2(N) bits of theoretical entropy. Human modifications, biased generators and restricted patterns reduce that value. Do not treat an entropy display as proof that a password cannot be compromised."]},
{heading:"Use a secure random number generator",text:["Browser implementations should use Web Crypto or another operating-system-backed CSPRNG. Math.random-style generators are not designed for secrets. Random bytes must also be mapped to the character set without introducing avoidable modulo bias when uniformity is important."]},
{heading:"Unique passwords stop credential reuse attacks",text:["Even a strong password becomes dangerous when reused. A breach at one service can expose credentials that attackers try elsewhere. Generate a different password for every account and store them in a reputable password manager rather than inventing a memorable shared pattern."]},
{heading:"Passphrases are another strategy",text:["Randomly selected words can produce secrets that are easier to type while retaining substantial entropy when enough words are chosen from a sufficiently large list. A human-written sentence or famous quotation is not equivalent to a randomly generated passphrase because attackers prioritize common language patterns."]},
{heading:"Character restrictions can reduce the search space",text:["Some legacy systems disallow symbols, truncate passwords or silently normalize characters. The generator should reflect the destination\u2019s actual rules without unnecessarily shrinking the alphabet. Always verify that the service accepted the complete generated value rather than silently cutting it off."]},
{heading:"Generation environment matters",text:["A password displayed on screen can leak through screenshots, clipboard history, browser extensions, logs or analytics. Avoid sending generated secrets to a server unless necessary. For high-value credentials, prefer a trusted local password manager or offline generation workflow."]},
{heading:"Passwords are only one authentication layer",text:["Multi-factor authentication, passkeys, rate limiting and breach monitoring can reduce account risk beyond password strength alone. Where passkeys are supported, they provide phishing-resistant authentication without requiring users to manage another shared secret."]},
{heading:"Practical use of this generator",text:["Choose a length comfortably above the service minimum, enable a broad allowed character set, generate a fresh value, store it immediately in a password manager and do not reuse it. Never paste an existing sensitive password into a random online tool merely to estimate its strength."]}
]},
"diff-checker":{title:"Diff Checker",sections:[
{heading:"A diff identifies changes between two versions",text:["A diff checker compares an original text with a revised text and marks additions, deletions and sometimes replacements. It does not decide whether a change is correct. Its job is to make differences visible so a reviewer can reason about them."]},
{heading:"Line-level and character-level diffs answer different questions",text:["Line diffs are effective for source code, configuration and prose where whole lines are meaningful. Character or word diffs reveal small edits inside a line. A useful interface may combine them: align changed lines first, then highlight the smaller changed spans."]},
{heading:"The longest common subsequence idea",text:["Many diff algorithms seek a common subsequence and describe the remaining material as insertions and deletions. Different algorithms can produce different but equally valid edit scripts, especially when repeated lines occur. A surprising highlight does not necessarily mean the underlying comparison is wrong."]},
{heading:"Whitespace can dominate the result",text:["Spaces, tabs, line endings and trailing whitespace are characters even when they are visually subtle. Formatting a file can therefore make every line appear changed. Ignore-whitespace modes are useful for semantic review, but they should be optional because whitespace is meaningful in formats such as Python, YAML and Markdown."]},
{heading:"Line-ending differences",text:["Windows commonly uses CRLF while Unix-like systems commonly use LF. Converting line endings can create a noisy diff with no meaningful content change. Normalizing line endings for display can help reviewers, while repository configuration such as .gitattributes can prevent recurring churn."]},
{heading:"Case and Unicode normalization",text:["Case-insensitive comparison may be useful for some datasets but dangerous for code or identifiers. Unicode text can also contain visually identical strings with different code-point compositions. A tool should make normalization choices explicit rather than silently changing comparison semantics."]},
{heading:"Large files require different UX",text:["A full character-level algorithm can become expensive on very large inputs. Chunking, line hashing, lazy rendering and collapsing unchanged regions improve performance and readability. Reviewers usually need context around changes, not thousands of unchanged lines rendered at full detail."]},
{heading:"Diffs for structured data",text:["JSON, XML and other structured formats can produce noisy textual diffs when keys reorder or formatting changes. Canonical formatting or a structure-aware diff may better reveal semantic changes. However, normalization itself can hide information, so preserve access to the original text."]},
{heading:"Security and privacy",text:["Diff inputs often contain source code, configuration, customer data or credentials. Understand whether comparison happens locally or whether text is transmitted to a server. Sensitive production secrets should not be pasted into an untrusted online comparison service."]},
{heading:"Review workflow",text:["First choose whether whitespace and case matter, compare the two versions, inspect each changed region with surrounding context, and verify high-impact edits in the original files. For code, run tests after review; for documents, check that moved text has not been mistaken for deletion plus insertion."]}
]},
"fd-comparison-calculator":{title:"FD Comparison Calculator",sections:[
{heading:"What an FD comparison actually measures",text:["A fixed-deposit comparison should answer more than which bank advertises the highest rate. The useful comparison is the maturity value and effective return produced by a principal amount after applying the quoted annual rate, tenure, compounding frequency and any tax assumptions. Two deposits with similar headline rates can finish with different proceeds when one compounds quarterly and another monthly, or when their tenures do not match exactly. Compare deposits on the same principal and holding period before treating the result as meaningful."]},
{heading:"Simple interest versus compound interest",text:["Most cumulative-deposit products credit interest periodically, so interest itself begins earning interest. For compound growth, maturity value follows principal multiplied by one plus the periodic rate raised to the number of compounding periods. A simple-interest shortcut understates the value whenever credited interest remains invested. The difference grows with longer tenures, higher rates and more frequent compounding. When checking the calculator manually, first convert the annual percentage rate into the rate per compounding period rather than multiplying the annual rate by years."]},
{heading:"Why compounding frequency changes maturity value",text:["A nominal annual rate does not completely describe an FD return. If interest is compounded quarterly, the annual rate is divided across four periods; monthly compounding uses twelve. More frequent compounding generally produces a slightly higher effective annual yield when the quoted nominal rate is unchanged. That difference may look small over one year but becomes visible on large deposits or multi-year terms. The comparison should therefore keep the displayed rate and the compounding convention together instead of ranking products by rate alone."]},
{heading:"Tenure and maturity dates",text:["FD terms are often quoted in months, days or combinations such as one year and six months. A comparison can become misleading if one option matures earlier and its proceeds are implicitly assumed to earn the same rate afterward. Use matching maturity horizons where possible. If terms differ, decide what happens to the earlier maturity: reinvest it at an assumed future rate, leave it in cash, or compare only through its own maturity date. Reinvestment risk matters because today’s attractive rate may not be available when a short FD rolls over."]},
{heading:"Premature withdrawal and liquidity",text:["The highest maturity value is not automatically the best deposit if there is a realistic chance the money will be needed early. Banks may reduce the applicable rate for premature withdrawal and may also impose a penalty. Some deposits are non-callable or restrict early access. Emergency funds therefore need a different evaluation from money that can genuinely remain locked until maturity. A ladder of deposits with staggered maturity dates can reduce liquidity pressure while still allowing part of the portfolio to earn term-deposit rates."]},
{heading:"Tax changes the usable return",text:["Interest on an FD is generally income rather than a tax-free increase in principal, so the investor’s tax position can materially change the net result. Tax deducted at source is not necessarily the final tax liability; it is typically a collection mechanism, while the ultimate tax depends on applicable rules and the depositor’s circumstances. A pretax maturity comparison should be labeled as such. For financial planning, compare the after-tax return with inflation and with alternatives that have different tax treatment rather than assuming the gross interest rate equals wealth growth."]},
{heading:"Cumulative and payout deposits",text:["A cumulative FD reinvests credited interest and is designed to maximize the amount available at maturity. A non-cumulative or payout FD distributes interest monthly, quarterly or at another interval, which may suit someone seeking cash flow. These are not equivalent even when the quoted rate is similar: distributed interest stops compounding inside the deposit unless the investor reinvests it elsewhere. The calculator result should therefore be interpreted according to whether interest remains invested or is paid out during the term."]},
{heading:"Inflation and real purchasing power",text:["An FD can grow in rupee terms while purchasing power grows much more slowly. If a deposit earns 7% before tax while inflation is 5%, the real gain is far below seven percentage points once compounding and tax are considered. This does not make an FD unsuitable; capital stability and known cash flows can be valuable objectives. It does mean that maturity value should not be confused with a guaranteed increase in real wealth. Long-term goals need an inflation-aware target amount."]},
{heading:"Credit and concentration risk",text:["A fixed deposit is often described as low risk, but the risk depends on the institution and product. Deposit-insurance limits, issuer strength, seniority and product structure matter. Splitting very large balances across institutions can change concentration and insurance exposure. A calculator cannot evaluate a bank’s solvency from an interest-rate input, so a few extra basis points should not override basic credit-risk checks. Confirm whether the product is actually a bank deposit or a different fixed-income instrument marketed with similar language."]},
{heading:"Worked comparison",text:["Suppose ₹500,000 is placed for three years. Option A quotes 7.0% compounded quarterly while Option B quotes 7.15% with a different compounding convention. The correct comparison calculates each periodic rate, number of periods and maturity amount independently; it does not simply multiply ₹500,000 by the annual rate and three years. After finding gross maturity values, subtract or estimate taxes consistently if an after-tax comparison is desired. Then check liquidity restrictions and whether both deposits truly share the same maturity horizon."]},
{heading:"Rate differences need scale",text:["A 0.10 percentage-point rate advantage can sound important but may translate into a modest rupee difference on a small principal or short tenure. Conversely, a seemingly minor difference can become meaningful on a large deposit held for years. Translate rate differences into actual maturity-value differences before switching institutions, breaking an existing FD or accepting stricter withdrawal conditions. This keeps the decision tied to money received rather than marketing percentages."]},
{heading:"How to use the comparison result",text:["Use the calculator to shortlist deposits under consistent assumptions, then verify the bank’s current rate card, tenure definition, compounding method, premature-withdrawal rule and eligibility conditions. Senior-citizen rates, special-tenure offers and callable versus non-callable deposits can change the result. The strongest choice is the deposit whose maturity value, access conditions, tax consequences and credit profile fit the purpose of the money—not simply the row with the largest gross number."]},
]},
"pixel-rem-converter":{title:"Pixel REM Converter",sections:[
{heading:"px and rem are CSS length units with different reference models",text:["A CSS pixel is a reference unit used by the rendering system; it is not guaranteed to equal one physical device pixel. rem means root em and is calculated from the computed font size of the document root element. The basic conversion is rem = px / root-font-size and px = rem \u00d7 root-font-size."]},
{heading:"The common 16px assumption",text:["Browsers commonly begin with a 16px default root font size, so 16px equals 1rem, 24px equals 1.5rem and 8px equals 0.5rem under that assumption. It is a convention, not a law. User settings, stylesheets or application design systems can change the root size."]},
{heading:"Worked conversion example",text:["With a 16px root, converting 20px gives 20 / 16 = 1.25rem. If the root becomes 20px, that same 1.25rem renders as 25px. This scaling behavior is the reason rem is often used for typography and spacing that should respond coherently to root-size changes."]},
{heading:"rem versus em",text:["rem always references the root font size. em is context dependent: for font-size it relates to the parent\u2019s computed size, while for many other properties it relates to the element\u2019s own font size. Nested em values can compound, whereas rem values provide a stable site-wide reference."]},
{heading:"Accessibility and user font preferences",text:["Relative units can help interfaces respond to user font-size preferences, but accessibility depends on the complete layout. Fixed heights, clipped containers or pixel-based breakpoints can still cause enlarged text to overlap or disappear. Test browser zoom and increased default font sizes rather than assuming unit choice alone solves accessibility."]},
{heading:"The 62.5% root-size trick",text:["Some stylesheets set html font-size to 62.5%, making 1rem roughly 10px when the browser default is 16px. This can simplify mental arithmetic, but it also changes the root scaling baseline and can interact with user preferences. Modern teams often keep the default and let tooling or design tokens handle conversion."]},
{heading:"Use rem where scalable rhythm helps",text:["Typography, margins, padding and component spacing often benefit from rem because a shared root scale keeps proportions coherent. Pixels remain useful for hairline borders, raster-aligned details and cases where a stable CSS-pixel measurement is intentional. There is no requirement to convert every pixel value."]},
{heading:"Responsive sizing may need more than conversion",text:["Changing 32px to 2rem does not make a heading fluid across viewport sizes; it only ties it to the root font size. clamp(), viewport-relative units, container queries and breakpoints solve different responsive problems. Choose units according to the behavior you want."]},
{heading:"Rounding and design tokens",text:["Conversions can produce long decimals, such as 15px / 16 = 0.9375rem. Preserve enough precision to avoid visible drift, but a design system may intentionally snap values to a spacing scale. Repeated arbitrary conversions are less maintainable than shared tokens for common sizes."]},
{heading:"Using the converter correctly",text:["Enter the pixel value and the root font size actually used by the target page. Verify the result in browser developer tools, especially if the root size changes by media query or user preference. Treat the converter as unit arithmetic, not as a guarantee that the resulting layout is responsive or accessible."]}
]},
"number-formatter":{title:"Number Formatter",sections:[
{heading:"Formatting changes presentation, not value",text:["A number formatter transforms how a numeric value is displayed. Thousands separators, decimal places, signs, percentages, currency symbols and compact notation can make the same underlying number easier to read without changing its mathematical value. That distinction matters in software: 1234.5 may be rendered as 1,234.50, 1.23K or a locale-specific equivalent, but calculations should continue to use the original numeric value rather than parsing a decorated display string whenever possible."]},
{heading:"Decimal places and rounding",text:["Choosing two decimal places is a display rule that normally requires rounding, not simply cutting off extra digits. Values exactly halfway between representable choices can be handled by different rounding modes, so financial or scientific applications should define the required rule rather than assume every environment behaves identically. Formatting 1.999 to two decimals should generally produce 2.00 under ordinary rounding. Truncation would produce 1.99 and communicates a different operation."]},
{heading:"Thousands and grouping separators",text:["Grouping improves readability for large numbers, but separators vary by locale. English-language output often uses a comma for thousands and a period for decimals, while many locales reverse those symbols or use spaces. The Indian numbering system groups higher digits differently, producing forms such as 12,34,567. A formatter intended for international users should rely on locale-aware APIs instead of manually inserting a comma every three digits."]},
{heading:"Percent formatting",text:["Percent formatting usually scales a decimal ratio for display: a stored value of 0.125 becomes 12.5%. This is a common source of hundred-fold errors when the input is already expressed as 12.5 and the formatter multiplies by 100 again. Decide whether the tool accepts a ratio or a human-entered percentage before applying the percent sign. The symbol itself does not tell you how the underlying value was represented."]},
{heading:"Currency is more than a symbol",text:["Prepending $ or ₹ does not create robust currency formatting. Currencies have different customary decimal digits, symbol positions and locale conventions, and the same dollar symbol can refer to multiple currencies. Applications handling money should carry the currency code alongside the amount where ambiguity matters. A formatter can improve presentation, but it cannot determine exchange rates or convert one currency into another unless explicit conversion logic exists."]},
{heading:"Negative numbers and accounting style",text:["Negative values may be shown with a minus sign, parentheses, a trailing sign or locale-specific conventions. Accounting displays often use parentheses and align currency symbols for scanning financial statements. Be careful with negative zero: floating-point calculations can produce a value whose sign is negative even though rounding displays 0.00. Normalizing tiny values before presentation may prevent confusing “-0.00” output."]},
{heading:"Scientific and compact notation",text:["Very large or very small values can be easier to understand using scientific notation or compact labels such as K, M and B. Compact notation sacrifices exact visible digits, so it is best for dashboards and summaries rather than identifiers or values where every unit matters. Scientific notation preserves scale explicitly through a power of ten and is common in technical work. The formatting choice should match whether the user needs magnitude, precision or exact transcription."]},
{heading:"Floating-point surprises",text:["Many programming languages represent ordinary decimal numbers using binary floating point. Some decimal fractions therefore cannot be stored exactly, which can surface as results such as 0.1 + 0.2 not being represented internally as an exact 0.3. A formatter may hide the extra digits, but it does not remove the underlying representation issue. Money and high-precision calculations may require decimal arithmetic or integer minor units before formatting."]},
{heading:"Parsing is a separate problem",text:["Formatting a number for output and parsing user-entered text into a number are different operations. A string such as “1,234” can mean one thousand two hundred thirty-four in one locale and a decimal value in another. Removing every punctuation mark is unsafe. Validate the expected locale and accepted syntax when converting formatted text back into numeric data."]},
{heading:"Identifiers should not be formatted as quantities",text:["Phone numbers, account numbers, ZIP/postal codes, product codes and long IDs may contain only digits but are not mathematical quantities. Applying numeric formatting can remove leading zeros, insert separators or trigger scientific notation. Keep identifiers as strings. The Number Formatter is appropriate when the digits represent a quantity whose presentation can legitimately change."]},
{heading:"Accessibility and copy behavior",text:["Decorative compact notation may be easy to scan visually but harder to copy into another system or understand with assistive technology if context is missing. Provide full values where precision matters, use meaningful labels, and avoid relying only on color or styling to communicate negative values. If users copy formatted output, consider whether they need a human-readable string or a machine-friendly raw value."]},
{heading:"Choosing a useful format",text:["Start with the audience and task. A finance table may need fixed decimal places and aligned grouping; analytics may prefer compact notation; scientific output may need significant figures; user interfaces should respect locale. Test zero, negatives, very large values, tiny decimals, halfway rounding cases and invalid input. Good formatting makes magnitude and precision clearer without pretending that the display has increased the accuracy of the original data."]},
]},
"text-case-converter":{title:"Text Case Converter",sections:[
{heading:"Case conversion changes letter presentation",text:["A text case converter transforms alphabetic casing while trying to preserve the underlying words and punctuation. Common modes include uppercase, lowercase, title case, sentence case, camelCase, PascalCase, snake_case and kebab-case. These modes solve different writing and programming tasks."]},
{heading:"Uppercase and lowercase are locale-sensitive",text:["Case mapping is not always a simple ASCII A-to-Z substitution. Languages can have special rules, such as dotted and dotless I in Turkish, and some characters map to multiple code points when case changes. A tool built only for English should say so rather than implying universal linguistic correctness."]},
{heading:"Sentence case requires detecting sentence boundaries",text:["A naive sentence-case algorithm lowercases everything and capitalizes the first character after a period. Real prose includes abbreviations, decimals, initials, quotation marks and line breaks, so sentence detection is imperfect without language-aware processing. Review names and acronyms after conversion."]},
{heading:"Title case is a style rule, not one universal algorithm",text:["Publishing styles disagree about whether short articles, conjunctions and prepositions should be lowercase and how words after colons are treated. A generic converter can provide a useful approximation, but formal documents should follow the required style guide such as APA, Chicago or an organization-specific convention."]},
{heading:"camelCase and PascalCase target identifiers",text:["camelCase typically begins with a lowercase word and capitalizes later word starts; PascalCase capitalizes the first word too. Converting prose to identifiers requires deciding what counts as a word and what to do with punctuation, digits, acronyms and non-Latin scripts."]},
{heading:"snake_case and kebab-case use separators",text:["snake_case joins normalized words with underscores, while kebab-case uses hyphens. They are common in programming, file names, URLs and CSS conventions, but target systems have different validity rules. A case converter does not automatically guarantee a valid database column, URL slug or programming-language identifier."]},
{heading:"Acronyms and proper nouns can be damaged",text:["Automatic lowercasing can turn NASA into Nasa, iPhone into Iphone or McDonald into Mcdonald. If the source contains brand capitalization, scientific symbols or person names, review the output manually. Mechanical case rules do not understand semantic exceptions."]},
{heading:"Whitespace and punctuation normalization",text:["Some conversion modes preserve spaces and punctuation, while identifier-style modes often replace or remove them. Multiple spaces, tabs, apostrophes, em dashes and underscores should be tested because they expose differences in tokenization. Decide whether the goal is typography or machine-friendly naming."]},
{heading:"Unicode and normalization",text:["Modern text includes accented characters, combining marks, emoji and scripts without uppercase/lowercase distinctions. A robust converter should preserve characters it cannot meaningfully case-map. Unicode normalization may also affect whether visually identical input has identical underlying code points."]},
{heading:"Practical workflow",text:["Paste a representative sample, choose the target convention, and review acronyms, names, punctuation, digits and non-English words before copying the result. For code-generation or bulk renaming, test collisions: two different source strings can normalize to the same identifier after punctuation and case are removed."]}
]},
}
export function CalculatorBatch50DeepDive({slug}:{slug:string}){const g=guides[slug];if(!g)return null;return <section className="mx-auto max-w-5xl px-4 py-10"><div className="rounded-2xl border border-gray-200 bg-white p-6 md:p-8"><h2 className="text-2xl md:text-3xl font-bold text-gray-900">{g.title}: Detailed Guide</h2><p className="mt-3 text-gray-700 leading-7">A detailed guide to the calculation logic, assumptions, scenarios, costs, thresholds, uncertainty and practical interpretation behind this specific tool.</p><div className="mt-8 space-y-8">{g.sections.map((s,i)=><article key={i}><h3 className="text-xl font-semibold text-gray-900">{s.heading}</h3>{s.text.map((p,j)=><p key={j} className="mt-3 text-gray-700 leading-7">{p}</p>)}</article>)}</div></div></section>}